{
  "tasks": [
    {
      "type": "cloze",
      "claim_id": "shaly-sand-effects-models.c3",
      "question": "Заполните пропуск в описании модели двойной воды.",
      "text": "Модель двойной воды разделяет воду на неподвижный связанный слой у поверхности глины и подвижную {{1}} воду.",
      "answers": [
        ["свободную", "свободная"]
      ],
      "explanation": "Модель выделяет неподвижную связанную воду и подвижную свободную воду, способную вытесняться углеводородами."
    },
    {
      "type": "order",
      "claim_id": "shaly-sand-effects-models.c3",
      "question": "Расположите слои воды по модели двойной воды в порядке удаленности от поверхности глины (от ближайшего к дальнему).",
      "items": [
        "Неподвижный связанный слой воды",
        "Подвижная свободная вода"
      ],
      "explanation": "Неподвижная связанная вода находится непосредственно у поверхности глины, а свободная вода может перемещаться дальше от нее."
    },
    {
      "type": "multi",
      "claim_id": "shaly-sand-effects-models.c4",
      "question": "В каких типах пород присутствие глин или сланцев может вызывать ошибки в оценке пористости и водонасыщенности по данным каротажа? (Выберите все верные варианты)",
      "options": [
        "Песчаники",
        "Известняки",
        "Доломиты",
        "Магматические граниты"
      ],
      "answer": [
        0,
        1,
        2
      ],
      "explanation": "Ошибки каротажа из-за глин и сланцев возникают в песчаниках, известняках и доломитах."
    }
  ],
  "card": {
    "front": "Почему важно учитывать электрофизические свойства глин, а не просто объем сланца при интерпретации каротажа?",
    "back": "Потому что сланцы и глины не тождественны, а их электрические свойства (связанная вода и проводимость) существенно влияют на расчет водонасыщенности и предотвращают ложные выводы о нефтеносности."
  }
}
